export function extractHoleTopology(mask,width,height,options={}){const minHoleArea=options.minHoleArea??8;const maxHoleRatio=options.maxHoleRatio??.45;const totalPixels=width*height;let minX=width,minY=height,maxX=-1,maxY=-1;let objectArea=0;for(let y=0;y<height;y++){const rowOffset=y*width;for(let x=0;x<width;x++){if(mask[rowOffset+x]>=128){objectArea++;if(x<minX)minX=x;if(x>maxX)maxX=x;if(y<minY)minY=y;if(y>maxY)maxY=y}}}if(objectArea<20||maxX<minX||maxY<minY){return{hole_count:0,aspect_ratio:1,hole_centroids:[],object_bbox:{minX:0,minY:0,maxX:0,maxY:0,width:0,height:0,area:0}}}const objW=maxX-minX+1;const objH=maxY-minY+1;const aspectRatio=Number((objW/Math.max(1,objH)).toFixed(4));const labels=new Uint8Array(totalPixels);for(let i=0;i<totalPixels;i++){if(mask[i]>=128){labels[i]=2}}const queue=new Int32Array(totalPixels);let qHead=0;let qTail=0;for(let x=0;x<width;x++){if(labels[x]===0){labels[x]=1;queue[qTail++]=x}const bIdx=(height-1)*width+x;if(labels[bIdx]===0){labels[bIdx]=1;queue[qTail++]=bIdx}}for(let y=1;y<height-1;y++){const lIdx=y*width;if(labels[lIdx]===0){labels[lIdx]=1;queue[qTail++]=lIdx}const rIdx=y*width+(width-1);if(labels[rIdx]===0){labels[rIdx]=1;queue[qTail++]=rIdx}}while(qHead<qTail){const idx=queue[qHead++];const cx=idx%width;const cy=idx/width|0;if(cx>0){const nIdx=idx-1;if(labels[nIdx]===0){labels[nIdx]=1;queue[qTail++]=nIdx}}if(cx<width-1){const nIdx=idx+1;if(labels[nIdx]===0){labels[nIdx]=1;queue[qTail++]=nIdx}}if(cy>0){const nIdx=idx-width;if(labels[nIdx]===0){labels[nIdx]=1;queue[qTail++]=nIdx}}if(cy<height-1){const nIdx=idx+width;if(labels[nIdx]===0){labels[nIdx]=1;queue[qTail++]=nIdx}}}const holes=[];const holeVisited=new Uint8Array(totalPixels);for(let y=minY;y<=maxY;y++){const rowOffset=y*width;for(let x=minX;x<=maxX;x++){const idx=rowOffset+x;if(labels[idx]===0&&holeVisited[idx]===0){let holeArea=0;let sumHoleX=0;let sumHoleY=0;let hHead=0;let hTail=0;const hQueue=new Int32Array(totalPixels);holeVisited[idx]=1;hQueue[hTail++]=idx;while(hHead<hTail){const cur=hQueue[hHead++];const hx=cur%width;const hy=cur/width|0;holeArea++;sumHoleX+=hx;sumHoleY+=hy;if(hx>minX){const n=cur-1;if(labels[n]===0&&holeVisited[n]===0){holeVisited[n]=1;hQueue[hTail++]=n}}if(hx<maxX){const n=cur+1;if(labels[n]===0&&holeVisited[n]===0){holeVisited[n]=1;hQueue[hTail++]=n}}if(hy>minY){const n=cur-width;if(labels[n]===0&&holeVisited[n]===0){holeVisited[n]=1;hQueue[hTail++]=n}}if(hy<maxY){const n=cur+width;if(labels[n]===0&&holeVisited[n]===0){holeVisited[n]=1;hQueue[hTail++]=n}}}if(holeArea>=minHoleArea&&holeArea<=objectArea*maxHoleRatio){const centerPixelX=sumHoleX/holeArea;const centerPixelY=sumHoleY/holeArea;const normX=Number(((centerPixelX-minX)/objW).toFixed(4));const normY=Number(((centerPixelY-minY)/objH).toFixed(4));const approxRadius=Math.sqrt(holeArea/Math.PI);const normRadius=Number((approxRadius/Math.max(objW,objH)).toFixed(4));holes.push({x:normX,y:normY,radius:normRadius,area:holeArea})}}}}holes.sort((a,b)=>a.x-b.x);return{hole_count:holes.length,aspect_ratio:aspectRatio,hole_centroids:holes,object_bbox:{minX:minX,minY:minY,maxX:maxX,maxY:maxY,width:objW,height:objH,area:objectArea}}}